const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');

console.log('=== 1. 读取正式新版 rule.json 并提取选集 lazy 脚本 ===');
const rulePath = path.resolve('rule.json');
const rule = JSON.parse(fs.readFileSync(rulePath, 'utf8'));

console.log('Title:', rule.title);
console.log('Version:', rule.version);

const dfr = rule.detail_find_rule;
const lines = dfr.split('\n');

// 找到包含 @lazyRule 的行
let lazyLine = '';
for (let i = 0; i < lines.length; i++) {
  if (lines[i].includes('@lazyRule=.js:')) {
    lazyLine = lines[i];
    break;
  }
}

if (!lazyLine) {
  throw new Error('未在 detail_find_rule 中找到 @lazyRule 模板行');
}

// 提取赋给 url 后面的 lazy 代码
const mark = "@lazyRule=.js:' + ";
const idx = lazyLine.indexOf(mark);
if (idx === -1) {
  throw new Error('未找到 lazyRule 前缀标志');
}

const rawLazyJson = lazyLine.slice(idx + mark.length).replace(/,\s*$/, '');
const lazyCode = JSON.parse(rawLazyJson);

fs.writeFileSync('new-generated-lazy.js', lazyCode, 'utf8');
console.log('成功生成 new-generated-lazy.js，字符数:', lazyCode.length);
console.log('代码预览 (前 200 字符):');
console.log(lazyCode.slice(0, 200));

console.log('\n=== 2. 使用新版选集脚本复核当前页绑定 (detail_find_rule) ===');
const rhinoJar = 'C:/Users/刘本录/.superagent/tools/rhino/1.7.14/rhino-1.7.14.jar';
const contextScript = 'D:/抖音/deepcloud/super-agent/skills/deepcloud-rule-engineer/scripts/test-rule-mobile-context.cjs';

const resDetail = spawnSync('node', [
  contextScript,
  '--rule', 'rule.json',
  '--source', 'new-generated-lazy.js',
  '--binding', 'detail_find_rule',
  '--rhino-jar', rhinoJar
], { encoding: 'utf8' });

console.log('detail_find_rule 检验结果 stdout:');
console.log(resDetail.stdout);
if (resDetail.stderr) console.error('stderr:', resDetail.stderr);

console.log('\n=== 3. 使用新版选集脚本复核首页绑定 (find_rule) ===');
const resHome = spawnSync('node', [
  contextScript,
  '--rule', 'rule.json',
  '--source', 'new-generated-lazy.js',
  '--binding', 'find_rule',
  '--rhino-jar', rhinoJar
], { encoding: 'utf8' });

console.log('find_rule 检验结果 stdout:');
console.log(resHome.stdout);
if (resHome.stderr) console.error('stderr:', resHome.stderr);

console.log('\n=== 4. 模拟选集生成与完整 PC 解析流程 ===');
// 模拟 detail_find_rule 中选集解析流程
const mockDetail = {
  id: 9999,
  name: '测试动漫',
  content: '简介内容',
  pic: 'https://pic.test.com/[REDACTED_REMOTE_URL]',
  parts: [
    {
      play: 'line1',
      play_zh: '直连线路一',
      part: ['第01集', '第02集', '第03集']
    },
    {
      play: 'line2',
      play_zh: '直连线路二',
      part: ['第01集', '第02集']
    }
  ]
};

// 提取 detail_find_rule 尾部业务代码（从 /*---DMGHG_CORE_END---*/ 之后）
const coreMarker = '/*---DMGHG_CORE_END---*/';
const dfrMarkerIdx = dfr.indexOf(coreMarker);
const businessCode = dfr.slice(dfrMarkerIdx + coreMarker.length);

const DMG_CONSTANTS = { origin: 'https://www.dmghg.com/[REDACTED_REMOTE_URL]' };
const MY_URL = 'https://www.dmghg.com/[REDACTED_REMOTE_URL]';

// 注入模拟运行环境
const simScope = {
  MY_URL,
  DMG_CONSTANTS,
  requestDmgApi: function() {
    return { data: mockDetail };
  },
  d: [],
  setResult: function(res) {
    this.d = res;
  }
};

const runSim = new Function(
  'MY_URL', 'DMG_CONSTANTS', 'requestDmgApi', 'd', 'setResult',
  businessCode + '\nreturn d;'
);

const renderedItems = runSim(
  simScope.MY_URL,
  simScope.DMG_CONSTANTS,
  simScope.requestDmgApi,
  simScope.d,
  simScope.setResult
);

console.log('选集生成总条目数:', renderedItems.length);
renderedItems.forEach((item, i) => {
  console.log(`条目 ${i+1}: [${item.col_type || 'normal'}] ${item.title} -> ${item.url ? item.url.slice(0, 60) + '...' : 'none'}`);
});

console.log('\n=== 5. 验证选集生成的 lazy 脚本可执行性与语法 ===');
// 取出第一集生成的 lazyRule
const firstEpUrl = renderedItems.find(it => it.title === '第01集').url;
const lazyRuleStr = firstEpUrl.slice(firstEpUrl.indexOf('@lazyRule=.js:') + '@lazyRule=.js:'.length);
console.log('首集提取到的 lazyRule 长度:', lazyRuleStr.length);

// 验证其在当前页绑定下的 cut 逻辑
const fakeMyRule = {
  find_rule: rule.detail_find_rule,
  title: rule.title,
  url: rule.url
};

const evalCoreCut = () => {
  const _r = fakeMyRule;
  const _fr = _r.find_rule || '';
  const _m = '/*---' + 'DMGHG_CORE_END---*/';
  const _idx = _fr.indexOf(_m);
  const _c = _idx !== -1 ? _fr.substring(0, _idx) : _fr;
  return { idx: _idx, len: _c.length, endsWith: _c.slice(-60) };
};

const cutResult = evalCoreCut();
console.log('切片结果: _idx =', cutResult.idx, ', 截取字符数 =', cutResult.len);
console.log('截取末尾代码片段:', JSON.stringify(cutResult.endsWith));

if (cutResult.idx === 234011 && cutResult.endsWith.includes('return candidates[0].url;')) {
  console.log('>>> 验证完全通过！切片位置精确截断在核心解密库末尾，完全排除了任何未闭合字符串字面量！');
} else {
  console.warn('>>> 警告：切片位置与预期不符！');
}

